from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import json,html
root=Path(__file__).resolve().parents[1];qa=root/'qa/phase3-1'
before=json.loads((qa/'baseline.json').read_text());after=json.loads((qa/'after.json').read_text());scan=json.loads((qa/'source-frame-scan.json').read_text());measure=[]
for b,a in zip(before,after):
    w,h=b['layout']['canvas'];mobile=b['width']<=768;old=min(w/(900 if mobile else 1600),h/1200)*(1.18 if mobile else 1.3)
    nw,nh=a['layout']['canvas'];scale=min(1,(nw-(16 if mobile else 72))/787,(nh-(84 if mobile else 90))/785)
    measure.append({'viewport':b['width'],'beforeCanvas':[w,h],'afterCanvas':[nw,nh],'beforeScale':old,'afterScale':scale,'frame0HeightBefore':666*old,'frame0HeightAfter':666*scale,'scaleChangePercent':(scale/old-1)*100,'worstSilhouetteHeight':785*scale,'nativeResolution':[720,960] if mobile else [1600,1200]})
(qa/'framing-comparison.json').write_text(json.dumps(measure,indent=2))
font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',20);small=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',15)
for width in [1440,390]:
    ims=[Image.open(qa/f'{phase}/studio-{width}-34-View.png').convert('RGB') for phase in ['before','after']];target=640 if width==1440 else 390;scaled=[im.resize((target,round(im.height*target/im.width)),Image.Resampling.LANCZOS) for im in ims]
    out=Image.new('RGB',(target*2+72,max(im.height for im in scaled)+110),'#0c1116');d=ImageDraw.Draw(out)
    for i,im in enumerate(scaled):x=24+i*(target+24);d.text((x,20),'BEFORE / PHASE 3' if i==0 else 'AFTER / PHASE 3.1',font=font,fill='#eae5dd');d.text((x,50),f'Same {width}px browser viewport; proportional screenshots',font=small,fill='#9ca8b2');out.paste(im,(x,85))
    out.save(qa/f'comparison-{width}.jpg',quality=95)
rows=''.join(f'<tr><td>{r["viewport"]} px</td><td>{r["frame0HeightBefore"]:.1f} px</td><td>{r["frame0HeightAfter"]:.1f} px</td><td>{r["scaleChangePercent"]:+.1f}%</td></tr>' for r in measure)
responsive=''.join(f'<article><h3>{w}px</h3><div class="pair"><figure><img src="before/studio-{w}-34-View.png"><figcaption>قبل — Studio</figcaption></figure><figure><img src="after/studio-{w}-34-View.png"><figcaption>بعد — Studio</figcaption></figure></div><div class="pair"><figure><img src="before/free-{w}-matched.png"><figcaption>قبل — Free 3D / نفس الزاوية</figcaption></figure><figure><img src="after/free-{w}-matched.png"><figcaption>بعد — Free 3D / نفس الزاوية</figcaption></figure></div></article>' for w in [360,390,768,1280,1440,1920])
poses=''.join(f'<article><h3>{name} / frame {frame}</h3><div class="pair"><figure><img src="after/matched-studio-{frame}.png"><figcaption>Cycles</figcaption></figure><figure><img src="after/matched-free-{frame}.png"><figcaption>Free 3D — كاميرا المصدر نفسها</figcaption></figure></div></article>' for name,frame in [('Front',66),('3/4',0),('Side',12),('Back',24)])
doc=f'''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VYREN / Phase 3.1 Evidence</title><style>body{{background:#10151a;color:#eae5dd;font:16px/1.75 Arial;margin:0}}main{{max-width:1440px;margin:auto;padding:36px}}h1{{font-size:40px;font-weight:400}}h2{{margin-top:64px;color:#d4ae77}}p{{max-width:900px;color:#b7c0c6}}article{{margin:28px 0;border:1px solid #323a42;padding:20px}}.pair{{display:grid;grid-template-columns:1fr 1fr;direction:ltr;align-items:start;gap:16px}}figure{{margin:0}}img,video{{width:100%;height:auto;background:#14191e}}figcaption{{color:#b7c0c6;font-size:13px}}table{{border-collapse:collapse;width:100%;text-align:right}}td,th{{border-bottom:1px solid #323a42;padding:12px}}a{{color:#d4ae77}}@media(max-width:700px){{main{{padding:16px}}.pair{{gap:8px}}article{{padding:8px}}}}</style><main><span>VYREN NOCTIS 01 / ENGINEERING EVIDENCE</span><h1>Phase 3.1 — Studio polish</h1><p>الصور والتسجيل من نسخة الإنتاج المحلية في Edge 155 على Windows. الهاتف محاكاة viewport؛ لا يمثل اختبار جهاز هاتف فعلي. صور المقارنة تحافظ على نسبة الأبعاد.</p><p>لم يُرفق التسجيل المشار إليه عند الثانية 55–57. لم يظهر جزء منفصل في فحص 72 صورة بدقتها الكاملة؛ أُصلح خلل مستقل ومؤكد في عرض زاوية قديمة أثناء العودة إلى Studio.</p><h2>جلسة المتصفح الفعلية</h2><video controls preload="metadata" src="recording/studio-polish-session.webm"></video><p>دوران كامل، زوايا Front/Side/Back، الوضعان، تبديل سريع، macro، fullscreen والعودة إلى تدفق الصفحة.</p><h2>الحجم المقاس من الألفا</h2><p>ارتفاع silhouette للإطار صفر محسوب من الألفا الأصلية ومن أبعاد canvas الفعلية. ضبط الهاتف 360px يترك مجالًا آمنًا لأعرض الزوايا؛ الزيادة الأساسية على الكمبيوتر والتابلت.</p><table><tr><th>Viewport</th><th>قبل</th><th>بعد</th><th>تغير الحجم</th></tr>{rows}</table><h2>مقارنة المصدر مع Free 3D</h2><p>الكاميرا مأخوذة من CAM_HERO. توجد فروق في نقل الضوء وخامات GLB المخبوزة؛ الصور لا تدعي تطابقًا فوتوغرافيًا كاملًا.</p>{poses}<h2>قبل / بعد — الأبعاد الستة</h2>{responsive}<h2>تدقيق الإطارات الأصلية</h2><img src="all-72-source-frames.jpg"><p><a href="full-resolution-alpha-scan.json">نتيجة فحص الألفا الكامل</a> · <a href="camera-matrix-validation.json">تدقيق مصفوفات الكاميرا</a> · <a href="scope-verification.json">الملفات المحفوظة</a> · <a href="test-results/results.json">نتائج الاختبارات</a></p></main></html>'''
(qa/'index.html').write_text(doc.replace('<img src=','<img loading="lazy" decoding="async" src='),encoding='utf-8');print(measure)
